<script setup lang="ts">
import {computed,onMounted,reactive,ref,toRaw,watch} from 'vue'
import {useRoute} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {http,dataOf} from '../api/http'
import {stepUpHeader,withStepUp} from '../api/stepUp'
import {useAuthStore} from '../stores/auth'

type Field=Record<string,any>&{__uiId:string;__optionsText:string;key:string;label:string;type:string;required:boolean;sensitive:boolean;maskType:string}
type Section=Record<string,any>&{__uiId:string;name:string;fields:Field[]}
type TemplateForm={id:number|null;name:string;type:string;tag:string;description:string;source:string;visibility:string;dataScopeId:number;sections:Section[];schemaDefinition:Record<string,any>}

const auth=useAuthStore(),route=useRoute()
const rows=ref<any[]>([]),total=ref(0),loading=ref(false),saving=ref(false)
const activeView=ref('ALL'),pageNum=ref(1),pageSize=24
const keyword=ref(''),typeFilter=ref(''),publishedFilter=ref(''),visibilityFilter=ref(''),enabledFilter=ref('')
const editorVisible=ref(false),detailVisible=ref(false),auditVisible=ref(false),versionVisible=ref(false)
const selected=ref<any|null>(null),versions=ref<any[]>([]),versionsLoading=ref(false)
const versionPreview=ref<any|null>(null)
const auditForm=reactive({auditStatus:1,auditComment:''})
const fieldTypes=[['text','文本'],['number','数值'],['date','日期'],['boolean','布尔'],['file','文件'],['object','对象'],['array','数组']]

const scopeIds=computed(()=>auth.user?.assignedScopes||[])
const isAdmin=computed(()=>auth.user?.roles.includes('ADMIN')||false)
const form=reactive<TemplateForm>(blankForm())
const totalFields=computed(()=>form.sections.reduce((sum,section)=>sum+section.fields.length,0))
const selectedFieldCount=computed(()=>(selected.value?.content?.sections||[]).reduce((sum:number,section:any)=>sum+(section.fields?.length||0),0))
const versionComparison=computed(()=>buildVersionComparison(versionPreview.value,selected.value))
const viewOptions=computed(()=>[
 {value:'ALL',label:'全部模板'},
 ...(isAdmin.value||auth.can('template:audit')?[{value:'REVIEW',label:'待我审核'}]:[]),
 {value:'MINE',label:'我的模板'},
 {value:'FAVORITES',label:'我的收藏'}
])
const currentViewLabel=computed(()=>viewOptions.value.find(item=>item.value===activeView.value)?.label||'全部模板')
const emptyMessage=computed(()=>activeView.value==='FAVORITES'?'还没有收藏模板':activeView.value==='REVIEW'?'暂无待审核模板':activeView.value==='MINE'?'还没有创建模板':'没有匹配的模板')

function uid(){return crypto.randomUUID()}
function clonePlain<T>(value:T):T{return structuredClone(toRaw(value))}
function blankField():Field{return{__uiId:uid(),__optionsText:'',key:'fieldKey',label:'字段名称',type:'text',required:false,sensitive:false,maskType:'GENERIC'}}
function blankSection():Section{return{__uiId:uid(),name:'基础信息',fields:[blankField()]}}
function blankForm():TemplateForm{return{id:null,name:'',type:'template',tag:'',description:'',source:'自主创建',visibility:'PRIVATE',dataScopeId:scopeIds.value?.[0]||0,sections:[blankSection()],schemaDefinition:{type:'object'}}}
function resetForm(){Object.assign(form,blankForm())}
function lifecycle(row:any){if(row.enabled===false)return'DISABLED';if(row.published)return'PUBLISHED';if(row.auditStatus!=null&&Number(row.auditStatus)===0)return'PENDING_REVIEW';if(row.auditStatus!=null&&Number(row.auditStatus)===2)return'REJECTED';if(row.visibility==='PRIVATE')return'PRIVATE_ACTIVE';return'DRAFT'}
function statusLabel(row:any){return({DISABLED:'已停用',PUBLISHED:'公共已发布',PENDING_REVIEW:'待审核',REJECTED:'已驳回',PRIVATE_ACTIVE:'私有可用',DRAFT:'公共草稿'} as any)[lifecycle(row)]}
function statusType(row:any){return lifecycle(row)==='PUBLISHED'?'success':lifecycle(row)==='PENDING_REVIEW'?'warning':lifecycle(row)==='REJECTED'||lifecycle(row)==='DISABLED'?'danger':'info'}
function fieldTypeLabel(type:string){return fieldTypes.find(option=>option[0]===type)?.[1]||type||'未定义'}
function formatTime(value:any){if(!value)return'—';const date=new Date(value);return Number.isNaN(date.getTime())?String(value):date.toLocaleString('zh-CN',{hour12:false})}
function fieldRules(field:any){const rules:string[]=[];if(field.required)rules.push('必填');if(field.unit)rules.push(`单位：${field.unit}`);if(field.min!=null||field.max!=null)rules.push(`数值：${field.min??'不限'} ～ ${field.max??'不限'}`);if(field.minLength!=null||field.maxLength!=null)rules.push(`长度：${field.minLength??0} ～ ${field.maxLength??'不限'}`);if(field.pattern)rules.push(`正则：${field.pattern}`);if(Array.isArray(field.options)&&field.options.length)rules.push(`${field.options.length} 个可选值`);if(field.sensitive)rules.push(`${field.maskType||'GENERIC'} 脱敏`);return rules}
function reviewTitle(row:any){const state=lifecycle(row);return state==='PRIVATE_ACTIVE'?'私有模板无需审核':state==='DRAFT'?'公共模板尚未提交审核':state==='PENDING_REVIEW'?'模板正在等待独立审核':state==='REJECTED'?'模板审核未通过':state==='PUBLISHED'?'模板已审核发布':'模板已停用'}
function reviewDescription(row:any){const state=lifecycle(row);return state==='PRIVATE_ACTIVE'?'当前仅创建者可见并可直接创建数据集；如需共享，请编辑为公共模板后提交审核。':state==='DRAFT'?'内容仍可编辑，确认无误后提交发布审核；创建者不能审核自己的模板。':state==='PENDING_REVIEW'?'内容已冻结，需由本数据域的其他审核员完成审核。':state==='REJECTED'?`请根据审核意见修改后重新提交。${row.auditComment?'审核意见：'+row.auditComment:''}`:state==='PUBLISHED'?'公共模板已通过独立审核，可供授权范围内的账号使用。':`停用原因：${row.disabledReason||'未填写'}`}
function displayMeta(key:string,value:any){if(value==null||value==='')return'—';if(key==='type')return fieldTypeLabel(String(value))==='未定义'?String(value):value==='template'?'完整模板':'模板片段';if(key==='visibility')return value==='PRIVATE'?'私有模板':'公共模板';if(key==='dataScopeId')return`数据域 #${value}`;return String(value)}
function fieldDescription(field:any){if(!field)return'—';const rules=fieldRules(field);return[`${fieldTypeLabel(field.type)} · ${field.required?'必填':'可选'}`,...rules.filter(rule=>rule!=='必填')].join('；')}
function flattenFields(template:any){const values=new Map<string,any>();for(const section of template?.content?.sections||[])for(const field of section.fields||[])values.set(String(field.key),{section:section.name||'未命名章节',field});return values}
function buildVersionComparison(before:any,after:any){if(!before||!after)return{metadata:[],fields:[],changedCount:0};const definitions=[['name','模板名称'],['type','模板类型'],['visibility','可见范围'],['tag','标签'],['description','模板说明'],['source','来源'],['dataScopeId','数据域']] as const;const metadata=definitions.map(([key,label])=>({key,label,before:displayMeta(key,before[key]),after:displayMeta(key,after[key]),changed:JSON.stringify(before[key]??null)!==JSON.stringify(after[key]??null)}));const previous=flattenFields(before),current=flattenFields(after),keys=[...new Set([...previous.keys(),...current.keys()])];const fields=keys.map(key=>{const oldValue=previous.get(key),newValue=current.get(key);const changed=oldValue&&newValue?JSON.stringify(oldValue)!==JSON.stringify(newValue):true;return{key,label:newValue?.field?.label||oldValue?.field?.label||key,beforeSection:oldValue?.section||'—',afterSection:newValue?.section||'—',before:fieldDescription(oldValue?.field),after:fieldDescription(newValue?.field),status:!oldValue?'ADDED':!newValue?'REMOVED':changed?'CHANGED':'UNCHANGED'}});return{metadata,fields,changedCount:metadata.filter(item=>item.changed).length+fields.filter(item=>item.status!=='UNCHANGED').length}}
function owns(row:any){return isAdmin.value||Number(row.creatorId)===Number(auth.user?.id)}
function canEdit(row:any){return auth.can('template:update')&&owns(row)&&!row.published&&lifecycle(row)!=='PENDING_REVIEW'}
function canDelete(row:any){return auth.can('template:delete')&&owns(row)&&!row.published&&lifecycle(row)!=='PENDING_REVIEW'}
function canSubmit(row:any){return auth.can('template:publish')&&owns(row)&&row.visibility==='PUBLIC'&&!row.published&&lifecycle(row)!=='PENDING_REVIEW'}
function canAudit(row:any){if(typeof row?.canAudit==='boolean')return row.canAudit;return(isAdmin.value||auth.can('template:audit'))&&(isAdmin.value||auth.user?.assignedScopes?.map(Number).includes(Number(row.dataScopeId)))&&lifecycle(row)==='PENDING_REVIEW'&&Number(row.creatorId)!==Number(auth.user?.id)}
function auditRestriction(row:any){if(row?.auditRestriction)return row.auditRestriction;if(Number(row?.creatorId)===Number(auth.user?.id))return'为确保职责分离，创建者不能审核自己的模板';if(!isAdmin.value&&!auth.can('template:audit'))return'当前账号未授予模板审核权限';if(!isAdmin.value&&!auth.user?.assignedScopes?.map(Number).includes(Number(row?.dataScopeId)))return`当前账号未直接授权该模板所属数据域 #${row?.dataScopeId}`;return'当前账号不具备该模板的审核资格'}
function canRestore(row:any){return auth.can('template:update')&&owns(row)&&lifecycle(row)!=='PENDING_REVIEW'}
function canToggleEnabled(row:any){return auth.can('template:audit')&&(isAdmin.value||auth.user?.assignedScopes?.includes(Number(row.dataScopeId)))&&row.visibility==='PUBLIC'&&row.published}
function canViewVersions(row:any){return owns(row)||(auth.can('template:audit')&&(isAdmin.value||auth.user?.assignedScopes?.includes(Number(row.dataScopeId))))}

async function load(){loading.value=true;try{const params:any={view:activeView.value,keyword:keyword.value||undefined,type:typeFilter.value||undefined,visibility:visibilityFilter.value||undefined,pageNum:pageNum.value,pageSize};if(publishedFilter.value!=='')params.published=publishedFilter.value==='true';if(enabledFilter.value!=='')params.enabled=enabledFilter.value==='true';const page=dataOf<any>(await http.get('/templates',{params}));rows.value=page.list;total.value=page.total}finally{loading.value=false}}
function search(){pageNum.value=1;load()}
function switchView(value:string){activeView.value=value;search()}
async function detail(rowOrId:any){const id=typeof rowOrId==='object'?rowOrId.id:rowOrId;selected.value=dataOf(await http.get(`/templates/${id}`));detailVisible.value=true;versions.value=[];if(canViewVersions(selected.value)){versionsLoading.value=true;try{versions.value=dataOf(await http.get(`/templates/${id}/versions`))}finally{versionsLoading.value=false}}}

function hydrateField(raw:any):Field{return{...clonePlain(raw),__uiId:uid(),__optionsText:Array.isArray(raw?.options)?JSON.stringify(raw.options):'',key:String(raw?.key||''),label:String(raw?.label||''),type:String(raw?.type||'text'),required:Boolean(raw?.required),sensitive:Boolean(raw?.sensitive),maskType:String(raw?.maskType||'GENERIC')}}
function hydrateSection(raw:any,index:number):Section{return{...clonePlain(raw),__uiId:uid(),name:String(raw?.name||`章节 ${index+1}`),fields:Array.isArray(raw?.fields)?raw.fields.map(hydrateField):[]}}
function edit(row:any){const content=row.content||{};const sections=Array.isArray(content.sections)?content.sections.map(hydrateSection):[hydrateSection({name:'基础信息',fields:[]},0)];Object.assign(form,{id:row.id,name:row.name,type:row.type,tag:row.tag||'',description:row.description||'',source:row.source||'自主创建',visibility:row.visibility||'PRIVATE',dataScopeId:Number(row.dataScopeId),sections,schemaDefinition:clonePlain(row.schemaDefinition||{type:'object'})});editorVisible.value=true}
async function openEdit(row:any){const value=dataOf<any>(await http.get(`/templates/${row.id}`));edit(value)}
function create(){if(!scopeIds.value.length)return ElMessage.warning('当前账号没有直接数据域授权，选择性共享不能用于创建模板');resetForm();editorVisible.value=true}
function cloneAsDraft(row:any){edit(row);form.id=null;form.name=`${row.name}（新版本）`;form.source=`基于模板 #${row.id} v${row.version}`;editorVisible.value=true}
function addSection(){form.sections.push({__uiId:uid(),name:`章节 ${form.sections.length+1}`,fields:[blankField()]})}
function removeSection(index:number){if(form.sections.length===1)return ElMessage.warning('模板至少保留一个章节');form.sections.splice(index,1)}
function addField(section:Section){const index=form.sections.flatMap(s=>s.fields).length+1;section.fields.push({...blankField(),key:`field${index}`,label:`字段 ${index}`})}
function removeField(section:Section,index:number){section.fields.splice(index,1)}

function parseOptions(text:string,label:string){const source=text.trim();if(!source)return undefined;if(source.startsWith('[')){try{const value=JSON.parse(source);if(!Array.isArray(value))throw new Error();return value}catch{throw new Error(`${label}的可选值须为 JSON 数组，或使用逗号分隔文本`)}}return source.split(',').map(v=>v.trim()).filter(Boolean)}
function cleanField(field:Field){const value:any={...field};delete value.__uiId;delete value.__optionsText;value.key=value.key.trim();value.label=value.label.trim();const options=parseOptions(field.__optionsText,value.label||value.key);if(options)value.options=options;else delete value.options;for(const key of ['unit','pattern'])if(value[key]!=null&&!String(value[key]).trim())delete value[key];for(const key of ['min','max','minLength','maxLength'])if(value[key]==null||value[key]==='')delete value[key];return value}
function schemaProperty(field:any,existing:any){const value:any={...clonePlain(existing||{})};for(const key of ['type','format','description','minimum','maximum','minLength','maxLength','pattern','enum'])delete value[key];if(field.type==='date'){value.type='string';value.format=existing?.format==='date-time'?'date-time':'date'}else if(field.type==='file'){value.type='string';value.format='binary'}else value.type=field.type==='text'?'string':field.type;value.description=field.label;if(field.min!=null)value.minimum=Number(field.min);if(field.max!=null)value.maximum=Number(field.max);if(field.minLength!=null)value.minLength=Number(field.minLength);if(field.maxLength!=null)value.maxLength=Number(field.maxLength);if(field.pattern)value.pattern=field.pattern;if(Array.isArray(field.options))value.enum=clonePlain(field.options);return value}
function payload(){const sections=form.sections.map(section=>{const value:any={...section,name:section.name.trim(),fields:section.fields.map(cleanField)};delete value.__uiId;return value});const fields=sections.flatMap(s=>s.fields);if(!fields.length)throw new Error('模板至少需要一个字段');if(fields.length===1&&fields[0].key==='fieldKey'&&fields[0].label==='字段名称')throw new Error('请先把默认占位字段“字段名称 / fieldKey”修改为实际业务字段');const keys=new Set<string>();for(const field of fields){if(!/^[A-Za-z][A-Za-z0-9_]{0,63}$/.test(field.key))throw new Error(`字段 key“${field.key}”格式不正确`);if(keys.has(field.key))throw new Error(`字段 key“${field.key}”重复`);keys.add(field.key);if(!field.label)throw new Error('字段名称不能为空');if(field.min!=null&&field.max!=null&&Number(field.min)>Number(field.max))throw new Error(`${field.label}的最小值不能大于最大值`);if(field.minLength!=null&&field.maxLength!=null&&Number(field.minLength)>Number(field.maxLength))throw new Error(`${field.label}的最小长度不能大于最大长度`);if(field.pattern)try{new RegExp(field.pattern)}catch{throw new Error(`${field.label}的正则表达式不正确`)}}
 const previous=form.schemaDefinition?.properties||{};const schema:any={...clonePlain(form.schemaDefinition||{}),type:'object',required:fields.filter(f=>f.required).map(f=>f.key),properties:{}};for(const field of fields)schema.properties[field.key]=schemaProperty(field,previous[field.key]);return{name:form.name.trim(),type:form.type,tag:form.tag.trim(),description:form.description.trim(),source:form.source.trim(),visibility:form.visibility,dataScopeId:form.dataScopeId,content:{sections},schemaDefinition:schema}}
async function save(){if(!form.name.trim())return ElMessage.warning('请输入模板名称');saving.value=true;try{const body=payload();if(form.id)await http.put(`/templates/${form.id}`,body);else await http.post('/templates',body);ElMessage.success(form.id?'模板已更新并保存版本快照':'模板已创建');editorVisible.value=false;await load();if(form.id&&detailVisible.value)await detail(form.id)}catch(error:any){if(!error?.response)ElMessage.error(error.message||'模板内容不正确')}finally{saving.value=false}}
async function toggleFavorite(row:any){const removing=Boolean(row.favorited);if(removing)await http.delete(`/templates/${row.id}/favorite`);else await http.put(`/templates/${row.id}/favorite`);row.favorited=!removing;if(selected.value?.id===row.id)selected.value.favorited=row.favorited;if(removing&&activeView.value==='FAVORITES')await load()}
async function submit(row:any){await ElMessageBox.confirm(`提交“${row.name}”后，模板在审核完成前将被冻结。`,'提交发布审核',{type:'warning'});await http.post(`/templates/${row.id}/publish`);ElMessage.success('已提交独立审核');await load();await detail(row.id)}
function openAudit(row:any){selected.value=row;auditForm.auditStatus=1;auditForm.auditComment='';auditVisible.value=true}
async function audit(){if(auditForm.auditStatus===2&&!auditForm.auditComment.trim())return ElMessage.warning('驳回时必须填写审核意见');await http.post(`/templates/${selected.value.id}/audit`,auditForm);ElMessage.success(auditForm.auditStatus===1?'模板已审核发布':'模板已驳回');auditVisible.value=false;await load();await detail(selected.value.id)}
async function remove(row:any){await ElMessageBox.confirm(`确认删除草稿“${row.name}”？删除后无法恢复。`,'删除模板',{type:'warning'});const endpoint=`/templates/${row.id}`;await withStepUp({purpose:'DELETE',method:'DELETE',target:endpoint,label:`删除模板“${row.name}”`},token=>http.delete(endpoint,{headers:stepUpHeader(token)}));ElMessage.success('模板已删除');detailVisible.value=false;await load()}
async function showVersion(row:any){versionPreview.value=dataOf(await http.get(`/templates/${selected.value.id}/versions/${row.version}`));versionVisible.value=true}
async function restoreVersion(row:any){const sourceId=selected.value.id;await ElMessageBox.confirm(`将 v${row.version} 的完整内容复制为一个可追溯的新草稿。原模板的发布状态及已有数据集引用不会改变。`,'恢复历史版本',{type:'warning'});const result=dataOf<any>(await http.post(`/templates/${sourceId}/versions/${row.version}/restore`));ElMessage.success(`已生成新草稿 #${result.id}`);versionVisible.value=false;await load();await detail(result.id)}
async function toggleEnabled(row:any){const action=row.enabled?'停用':'重新启用';const {value}=await ElMessageBox.prompt(`请输入${action}“${row.name}”的原因`,`${action}模板`,{inputPattern:/\S+/,inputErrorMessage:'必须填写原因',type:'warning'});await http.put(`/templates/${row.id}/enabled`,{enabled:!row.enabled,reason:value});ElMessage.success(`模板已${action}`);await load();await detail(row.id)}

watch(()=>route.query.focus,async value=>{if(value)await detail(Number(value))})
onMounted(async()=>{await load();if(route.query.focus)await detail(Number(route.query.focus))})
</script>

<template><div class="page"><div class="page-head"><div><h1 class="page-title">模板中心</h1><div class="page-subtitle">可视化配置章节、字段和校验规则，{{currentViewLabel}}共 {{total}} 个模板</div></div><el-button v-if="auth.can('template:create')" type="primary" @click="create">新建模板</el-button></div>
 <nav class="template-view-tabs surface" aria-label="模板视图"><button v-for="item in viewOptions" :key="item.value" :class="{active:activeView===item.value}" @click="switchView(item.value)"><span>{{item.label}}</span><i v-if="activeView===item.value">{{total}}</i></button></nav>
 <div class="surface toolbar"><el-input v-model="keyword" placeholder="搜索名称或标签" clearable style="width:240px" @keyup.enter="search"/><el-select v-model="typeFilter" placeholder="全部类型" clearable style="width:130px"><el-option label="完整模板" value="template"/><el-option label="模板片段" value="fragment"/></el-select><el-select v-model="visibilityFilter" placeholder="全部范围" clearable style="width:130px"><el-option label="本人私有" value="PRIVATE"/><el-option label="公共模板" value="PUBLIC"/></el-select><el-select v-model="publishedFilter" placeholder="全部发布状态" style="width:140px"><el-option label="全部发布状态" value=""/><el-option label="已发布" value="true"/><el-option label="未发布" value="false"/></el-select><el-select v-model="enabledFilter" placeholder="全部启停状态" style="width:140px"><el-option label="全部启停状态" value=""/><el-option label="启用" value="true"/><el-option label="停用" value="false"/></el-select><el-button @click="search">查询</el-button></div>
 <div class="template-grid" v-loading="loading"><article v-for="row in rows" :key="row.id" class="template-card surface" @click="detail(row)"><div class="card-top"><span class="kind">{{row.type==='template'?'完整模板':'模板片段'}}</span><button :title="row.favorited?'取消收藏':'收藏'" @click.stop="toggleFavorite(row)">{{row.favorited?'★':'☆'}}</button></div><h3>{{row.name}}</h3><p>{{row.description||'暂无模板说明'}}</p><div class="tags"><el-tag v-for="tag in (row.tag||'').split(',').filter(Boolean)" :key="tag" size="small" effect="plain">{{tag}}</el-tag></div><footer><span>v{{row.version}} · {{row.creatorName}}</span><el-tag :type="statusType(row)" size="small">{{statusLabel(row)}}</el-tag></footer></article><div v-if="!rows.length" class="empty-note">{{emptyMessage}}</div></div><el-pagination v-if="total>pageSize" v-model:current-page="pageNum" :page-size="pageSize" :total="total" layout="prev, pager, next, total" class="template-pagination" @current-change="load"/>

 <el-dialog v-model="detailVisible" class="template-detail-dialog" width="min(980px,94vw)" top="4vh" append-to-body destroy-on-close>
  <template #header><div v-if="selected" class="detail-title"><span class="detail-title-icon">◇</span><div><div class="detail-title-line"><h2>{{selected.name}}</h2><el-tag :type="statusType(selected)" size="small">{{statusLabel(selected)}}</el-tag></div><p>{{selected.description||'暂无模板说明'}}</p></div></div></template>
  <template v-if="selected">
   <section class="detail-overview"><div class="overview-main"><span class="section-kicker">TEMPLATE OVERVIEW</span><h3>模板概览</h3><div class="detail-tags"><el-tag v-for="tag in (selected.tag||'').split(',').filter(Boolean)" :key="tag" size="small" effect="plain">{{tag}}</el-tag><span v-if="!selected.tag">暂无标签</span></div></div><div class="overview-stats"><div><small>模板类型</small><b>{{selected.type==='template'?'完整模板':'模板片段'}}</b></div><div><small>结构规模</small><b>{{selected.content?.sections?.length||0}} 章 / {{selectedFieldCount}} 字段</b></div><div><small>所属数据域</small><b>#{{selected.dataScopeId}}</b></div><div><small>版本与创建者</small><b>v{{selected.version}} · {{selected.creatorName}}</b></div></div></section>
   <section class="review-banner" :class="`is-${lifecycle(selected).toLowerCase()}`"><span class="review-icon">{{selected.visibility==='PRIVATE'?'⌁':lifecycle(selected)==='PUBLISHED'?'✓':'!'}}</span><div><b>{{reviewTitle(selected)}}</b><p>{{reviewDescription(selected)}}</p></div><el-tag effect="plain">{{selected.visibility==='PRIVATE'?'仅本人可见':'公共范围'}}</el-tag></section>
   <div class="detail-actions"><el-button v-if="canEdit(selected)" type="primary" @click="openEdit(selected)">编辑草稿</el-button><el-button v-if="canSubmit(selected)" type="success" @click="submit(selected)">提交发布审核</el-button><el-button v-if="canAudit(selected)" type="warning" @click="openAudit(selected)">独立审核</el-button><el-tooltip v-else-if="lifecycle(selected)==='PENDING_REVIEW'" :content="auditRestriction(selected)" placement="top"><span class="disabled-audit-action"><el-button type="warning" disabled>无审核权限</el-button><small>{{auditRestriction(selected)}}</small></span></el-tooltip><el-button v-if="canToggleEnabled(selected)" :type="selected.enabled?'danger':'success'" plain @click="toggleEnabled(selected)">{{selected.enabled?'停用模板':'重新启用'}}</el-button><el-button v-if="selected.published&&auth.can('template:create')" @click="cloneAsDraft(selected)">复制为新草稿</el-button><el-button @click="toggleFavorite(selected)">{{selected.favorited?'取消收藏':'收藏'}}</el-button><el-button v-if="canDelete(selected)" type="danger" plain @click="remove(selected)">删除模板</el-button></div>
   <div class="detail-heading"><div><span class="section-kicker">SCHEMA STRUCTURE</span><h3>章节与字段</h3></div><span>完整展示字段类型、约束和脱敏规则</span></div>
   <section v-for="(section,index) in selected.content?.sections||[]" :key="index" class="detail-section"><header><div><span>{{String(Number(index)+1).padStart(2,'0')}}</span><h4>{{section.name||`章节 ${Number(index)+1}`}}</h4></div><small>{{section.fields?.length||0}} 个字段</small></header><div class="detail-fields"><article v-for="(field,fieldIndex) in section.fields||[]" :key="field.key"><span class="detail-field-index">{{String(Number(fieldIndex)+1).padStart(2,'0')}}</span><div class="detail-field-name"><b>{{field.label}}</b><code>{{field.key}}</code></div><span class="detail-field-type">{{fieldTypeLabel(field.type)}}</span><div class="detail-field-rules"><span v-for="rule in fieldRules(field)" :key="rule" :title="rule">{{rule}}</span><em v-if="!fieldRules(field).length">无附加约束</em></div></article><div v-if="!section.fields?.length" class="detail-empty">本章节暂无字段</div></div></section>
   <section v-if="canViewVersions(selected)" class="history-section"><div class="detail-heading"><div><span class="section-kicker">VERSION HISTORY</span><h3>版本历史</h3></div><span>每次保存都会生成不可变版本快照</span></div><el-table :data="versions" v-loading="versionsLoading"><el-table-column label="版本" width="80"><template #default="{row}"><b>v{{row.version}}</b></template></el-table-column><el-table-column prop="changeReason" label="变更说明" min-width="220"/><el-table-column prop="createdByName" label="操作人" width="120"/><el-table-column label="时间" width="180"><template #default="{row}">{{formatTime(row.createdTime)}}</template></el-table-column><el-table-column label="操作" width="150" align="right"><template #default="{row}"><el-button link type="primary" @click="showVersion(row)">查看比较</el-button><el-button v-if="canRestore(selected)&&Number(row.version)!==Number(selected.version)" link type="warning" @click="restoreVersion(row)">恢复</el-button></template></el-table-column></el-table></section>
  </template>
  <template #footer><div class="detail-footer"><span>模板 ID：#{{selected?.id}} · 来源：{{selected?.source||'自主创建'}}</span><el-button @click="detailVisible=false">关闭</el-button></div></template>
 </el-dialog>

 <el-dialog v-model="editorVisible" class="template-editor-dialog" width="min(1080px,94vw)" top="3vh" append-to-body destroy-on-close>
  <template #header>
   <div class="editor-title"><span class="editor-title-icon">◇</span><div><h2>{{form.id?'编辑模板草稿':'新建模板'}}</h2><p>定义可复用的数据结构、字段约束与访问范围</p></div><span class="draft-badge">草稿</span></div>
  </template>
  <div class="editor-progress"><div class="progress-item is-active"><i>1</i><span><b>基本信息</b><small>名称与使用范围</small></span></div><div class="progress-line"></div><div class="progress-item is-active"><i>2</i><span><b>结构设计</b><small>{{form.sections.length}} 个章节 · {{totalFields}} 个字段</small></span></div></div>
  <el-form label-position="top" class="editor-form">
   <section class="editor-panel meta-panel">
    <div class="panel-heading"><div><span class="section-kicker">BASIC INFORMATION</span><h3>基本信息</h3></div><p>带 <em>*</em> 的内容为必填项</p></div>
    <div class="meta-grid meta-grid-primary"><el-form-item label="模板名称 *"><el-input v-model="form.name" maxlength="200" show-word-limit placeholder="例如：设备巡检记录模板"/></el-form-item><el-form-item label="模板类型"><el-select v-model="form.type"><el-option label="完整模板" value="template"/><el-option label="模板片段" value="fragment"/></el-select></el-form-item><el-form-item label="可见范围"><el-select v-model="form.visibility"><el-option label="私有模板（仅本人使用）" value="PRIVATE"/><el-option label="公共模板（审核后共享）" value="PUBLIC"/></el-select></el-form-item></div>
    <div class="meta-grid"><el-form-item label="所属数据域"><el-select v-model="form.dataScopeId"><el-option v-for="scope in scopeIds" :key="scope" :label="`数据域 #${scope}`" :value="scope"/></el-select></el-form-item><el-form-item label="标签"><el-input v-model="form.tag" placeholder="多个标签以逗号分隔"/></el-form-item><el-form-item label="来源"><el-input v-model="form.source" placeholder="模板来源"/></el-form-item></div>
    <el-form-item label="模板说明"><el-input v-model="form.description" type="textarea" :rows="2" maxlength="500" show-word-limit placeholder="简单说明模板的适用场景和使用方式"/></el-form-item>
    <div class="visibility-tip" :class="form.visibility==='PRIVATE'?'is-private':'is-public'"><span>{{form.visibility==='PRIVATE'?'⌁':'!'}}</span><div><b>{{form.visibility==='PRIVATE'?'私有模板可直接使用':'公共模板需要独立审核'}}</b><p>{{form.visibility==='PRIVATE'?'保存后仅你可见，可直接用于创建数据集。':'先保存为草稿，提交并审核通过后才能供其他账号使用。'}}</p></div></div>
   </section>
  </el-form>
  <section class="structure-panel">
   <div class="builder-head"><div><span class="section-kicker">SCHEMA DESIGN</span><h3>章节与字段</h3><p>按业务结构组织字段，并配置格式校验、必填与脱敏规则。</p></div><el-button type="primary" plain @click="addSection"><span class="button-plus">＋</span> 添加章节</el-button></div>
   <section v-for="(section,sectionIndex) in form.sections" :key="section.__uiId" class="builder-section">
    <header><div class="section-identity"><span class="section-index">{{String(sectionIndex+1).padStart(2,'0')}}</span><el-input v-model="section.name" placeholder="章节名称"/></div><div class="section-actions"><span>{{section.fields.length}} 个字段</span><el-button @click="addField(section)">＋ 添加字段</el-button><el-button type="danger" link :disabled="form.sections.length===1" @click="removeSection(sectionIndex)">删除章节</el-button></div></header>
    <div class="field-editor" v-for="(field,fieldIndex) in section.fields" :key="field.__uiId">
     <div class="field-toolbar"><div><span class="field-number">FIELD {{String(fieldIndex+1).padStart(2,'0')}}</span><b>{{field.label||'未命名字段'}}</b></div><el-button type="danger" link @click="removeField(section,fieldIndex)">删除字段</el-button></div>
     <div class="field-main"><label><span>字段名称</span><el-input v-model="field.label" placeholder="例如：设备名称"/></label><label><span>字段 Key</span><el-input v-model="field.key" class="mono" placeholder="fieldKey"/></label><label><span>数据类型</span><el-select v-model="field.type"><el-option v-for="type in fieldTypes" :key="type[0]" :label="type[1]" :value="type[0]"/></el-select></label><div class="switch-box"><span>必填字段</span><el-switch v-model="field.required" inline-prompt active-text="是" inactive-text="否"/></div></div>
     <div class="constraint-title"><span>校验与数据规则</span><i></i></div>
     <div class="constraints"><label><span>单位</span><el-input v-model="field.unit" placeholder="可选"/></label><label v-if="field.type==='number'"><span>最小值</span><el-input-number v-model="field.min" placeholder="不限"/></label><label v-if="field.type==='number'"><span>最大值</span><el-input-number v-model="field.max" placeholder="不限"/></label><label v-if="field.type==='text'||field.type==='string'"><span>最短长度</span><el-input-number v-model="field.minLength" :min="0" placeholder="不限"/></label><label v-if="field.type==='text'||field.type==='string'"><span>最长长度</span><el-input-number v-model="field.maxLength" :min="0" placeholder="不限"/></label><label v-if="field.type==='text'||field.type==='string'" class="constraint-wide"><span>正则表达式</span><el-input v-model="field.pattern" class="mono" placeholder="可选，例如 ^[A-Z]+$"/></label><label class="constraint-wide"><span>可选值</span><el-input v-model="field.__optionsText" placeholder="JSON 数组或逗号分隔文本"/></label><div class="switch-box"><span>导出脱敏</span><el-switch v-model="field.sensitive" inline-prompt active-text="是" inactive-text="否"/></div><label v-if="field.sensitive"><span>脱敏方式</span><el-select v-model="field.maskType"><el-option label="通用掩码" value="GENERIC"/><el-option label="手机号" value="PHONE"/><el-option label="邮箱" value="EMAIL"/><el-option label="证件号" value="ID_CARD"/><el-option label="姓名" value="NAME"/></el-select></label></div>
    </div>
    <div v-if="!section.fields.length" class="empty-section"><span>＋</span><p>本章节尚无字段</p><el-button link type="primary" @click="addField(section)">添加第一个字段</el-button></div>
   </section>
  </section>
  <template #footer><div class="editor-footer"><span>内容将保存为草稿，你可以稍后继续编辑</span><div><el-button @click="editorVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存草稿</el-button></div></div></template>
 </el-dialog>

 <el-dialog v-model="auditVisible" title="模板独立审核" width="520" append-to-body destroy-on-close><el-alert title="仅拥有模板审核权限、且直接授权本数据域的审核员或管理员可操作；审核人不能是模板创建者。" type="warning" :closable="false"/><el-form label-position="top" style="margin-top:18px"><el-form-item label="审核结论"><el-radio-group v-model="auditForm.auditStatus"><el-radio-button :value="1">通过并发布</el-radio-button><el-radio-button :value="2">驳回</el-radio-button></el-radio-group></el-form-item><el-form-item label="审核意见"><el-input v-model="auditForm.auditComment" type="textarea" :rows="4"/></el-form-item></el-form><template #footer><el-button @click="auditVisible=false">取消</el-button><el-button type="primary" @click="audit">确认审核</el-button></template></el-dialog>

 <el-dialog v-model="versionVisible" class="version-compare-dialog" :title="versionPreview?`版本比较：v${versionPreview.version} → v${selected?.version}`:'版本比较'" width="min(920px,94vw)" top="5vh" append-to-body destroy-on-close><template v-if="versionPreview"><div class="version-meta"><el-tag>{{versionPreview.visibility==='PRIVATE'?'私有':'公共'}}</el-tag><span>{{versionPreview.changeReason}}</span><span>{{versionPreview.createdByName}} · {{formatTime(versionPreview.createdTime)}}</span><el-tag :type="versionComparison.changedCount?'warning':'success'">{{versionComparison.changedCount?`${versionComparison.changedCount} 项变化`:'内容一致'}}</el-tag></div>
  <section class="compare-block"><header><div><span class="section-kicker">BASIC CHANGES</span><h3>基本信息变化</h3></div><small>高亮项表示两个版本内容不同</small></header><div class="meta-compare-table"><div class="compare-table-head"><span>项目</span><span>历史版本 v{{versionPreview.version}}</span><span>当前版本 v{{selected?.version}}</span></div><div v-for="item in versionComparison.metadata" :key="item.key" :class="{changed:item.changed}"><b>{{item.label}}</b><span>{{item.before}}</span><span>{{item.after}}</span></div></div></section>
  <section class="compare-block"><header><div><span class="section-kicker">FIELD CHANGES</span><h3>章节与字段变化</h3></div><small>展示新增、删除、修改以及未变化字段</small></header><div class="field-compare-list"><article v-for="field in versionComparison.fields" :key="field.key" :class="`is-${field.status.toLowerCase()}`"><div class="field-change-name"><el-tag :type="field.status==='ADDED'?'success':field.status==='REMOVED'?'danger':field.status==='CHANGED'?'warning':'info'" size="small">{{field.status==='ADDED'?'新增':field.status==='REMOVED'?'删除':field.status==='CHANGED'?'修改':'未变化'}}</el-tag><div><b>{{field.label}}</b><code>{{field.key}}</code></div></div><div><small>历史版本 · {{field.beforeSection}}</small><p>{{field.before}}</p></div><span class="compare-arrow">→</span><div><small>当前版本 · {{field.afterSection}}</small><p>{{field.after}}</p></div></article><div v-if="!versionComparison.fields.length" class="compare-empty">两个版本都没有配置字段</div></div></section>
  <details class="raw-comparison"><summary>技术人员：查看原始数据</summary><div class="compare-grid"><section><h4>历史版本 v{{versionPreview.version}}</h4><pre>{{JSON.stringify({name:versionPreview.name,type:versionPreview.type,visibility:versionPreview.visibility,content:versionPreview.content,schemaDefinition:versionPreview.schemaDefinition},null,2)}}</pre></section><section><h4>当前版本 v{{selected?.version}}</h4><pre>{{JSON.stringify({name:selected?.name,type:selected?.type,visibility:selected?.visibility,content:selected?.content,schemaDefinition:selected?.schemaDefinition},null,2)}}</pre></section></div></details>
 </template><template #footer><el-button @click="versionVisible=false">关闭</el-button><el-button v-if="versionPreview&&canRestore(selected)&&Number(versionPreview.version)!==Number(selected?.version)" type="warning" @click="restoreVersion(versionPreview)">恢复为新草稿</el-button></template></el-dialog>
</div></template>

